-- =============================================================================================
-- NEXORA · procedures — dictionnaire des modèles de données de référence (schéma rdm)
-- Supply Chain Reference Data Model UN/CEFACT, release D23B : 141 ABIE et 1 725 BIE (BBIE / ASBIE).
-- Repris du livrable « NEXORA_WFE_SCRDM_PostgreSQL17.sql » (v1.0, 10 octobre 2026), sections 1 et 6.
-- Source machine : github.com/uncefact/spec-JSONschema — library/BuyShipPay/D23B.
-- Le Data Agent s'en sert pour proposer le chemin BIE de chaque champ (RG-REF-02).
-- =============================================================================================
CREATE SCHEMA IF NOT EXISTS rdm;
CREATE TYPE rdm.bie_kind AS ENUM ('ABIE', 'BBIE', 'ASBIE');

CREATE TABLE rdm.standard_release (
  release_id     integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  family         varchar(20)  NOT NULL,            -- BSP, SCRDM, MMT, CBM, WCO_DM
  release_code   varchar(10)  NOT NULL,            -- ex. D23B
  title          varchar(200) NOT NULL,
  source_uri     text,
  loaded_at      timestamptz  NOT NULL DEFAULT now(),
  UNIQUE (family, release_code)
);
COMMENT ON TABLE rdm.standard_release IS 'Publication versionnée d''un modèle de référence (UN/CEFACT, OMD).';

CREATE TABLE rdm.abie (
  release_id     integer      NOT NULL REFERENCES rdm.standard_release,
  abie_code      varchar(80)  NOT NULL,            -- nom technique, ex. consignment
  den            varchar(250) NOT NULL,            -- Dictionary Entry Name
  definition     text,
  depth_from_root smallint,
  is_root        boolean      NOT NULL DEFAULT false,
  PRIMARY KEY (release_id, abie_code)
);
COMMENT ON TABLE rdm.abie IS 'Aggregate Business Information Entity (classe du RDM).';

CREATE TABLE rdm.bie (
  release_id     integer      NOT NULL,
  abie_code      varchar(80)  NOT NULL,
  property_code  varchar(100) NOT NULL,            -- ex. grossWeight
  den            varchar(300) NOT NULL,            -- ex. Supply Chain_ Consignment. Gross Weight. Measure
  kind           rdm.bie_kind NOT NULL,            -- BBIE ou ASBIE
  cardinality    varchar(6)   NOT NULL CHECK (cardinality IN ('0..1','1..1','0..n','1..n')),
  data_type      varchar(100),                     -- BBIE : type de données (udt/qdt)
  target_abie    varchar(80),                      -- ASBIE : ABIE cible
  definition     text,
  PRIMARY KEY (release_id, abie_code, property_code),
  FOREIGN KEY (release_id, abie_code) REFERENCES rdm.abie,
  CHECK ((kind = 'ASBIE') = (target_abie IS NOT NULL))
);
COMMENT ON TABLE rdm.bie IS 'Propriétés des ABIE : BBIE (donnée simple) ou ASBIE (association vers un ABIE).';
CREATE INDEX ix_bie_target ON rdm.bie (release_id, target_abie) WHERE kind = 'ASBIE';

-- =====================================================================
-- 6. Données de référence et chargement du SCRDM D23B (UN/CEFACT)
-- Source : github.com/uncefact/spec-JSONschema — library/BuyShipPay/D23B
--          (UNECE-SCRDMMaster.json, UNECE-SCRDMContextCCL.json, UNECE-BSPContextCCL.json)
-- =====================================================================

-- Racine : SCRDM Master Message


-- Recherche plein texte sur les noms normalisés (DEN) et définitions
CREATE INDEX ix_bie_den ON rdm.bie USING gin (to_tsvector('simple', den || ' ' || coalesce(definition, '')));
